const HS_IDS = [['hs-km', 'hs-km-l'], ['hs-cost', 'hs-cost-l'], ['hs-kwh', 'hs-kwh-l']];
function applyStat(i, v) { $(HS_IDS[i][0]).textContent = v[i].value; $(HS_IDS[i][1]).textContent = v[i].label; }
